export type StyleScheme = 'dark' | 'light'

/** Matches KesselColorsConfig (src/renderer/kessel/config.ts). */
export interface StyleTerminalColors {
  foreground: number
  background: number
  palette: readonly number[]
  cursor: { text: number | null; cursor: number }
  selection: { text: number | null; background: number }
}

export interface StylePaletteMeta {
  id: string
  name: string
  schemes: readonly StyleScheme[]
  swatch: { bg: string; surface: string; elevated: string; accent: string; textPrimary: string; border: string }
  terminal: StyleTerminalColors
}

/** A user-adjustable knob the style's manifest advertises. The dial
 *  writes `token` as an inline custom property on <html>; values are
 *  per-user (localStorage `k2.dial.<styleId>.<dialId>`). */
export interface StyleDialMeta {
  id: string
  label: string
  /** CSS custom property the dial writes, e.g. --material-blur. */
  token: string
  min: number
  max: number
  step?: number
  /** Unit appended when writing the token, e.g. 'px'. */
  unit?: string
  /** Resting value when the user hasn't adjusted the dial. */
  default?: number
}

export interface StyleMeta {
  id: string
  name: string
  author: string
  description: string
  defaultPalette: string
  defaultPalettes: Partial<Record<StyleScheme, string>>
  capabilities: { gaps: boolean; backdrop: boolean; schemes: readonly StyleScheme[] }
  gapPresets: readonly string[]
  dials: readonly StyleDialMeta[]
  palettes: readonly StylePaletteMeta[]
  /** Optional WebGL text-weight gamma override. When absent, derived
   *  from the resolved palette's terminal background luminance
   *  (dark → 0.7, light → 1.2). See src/renderer/lib/text-gamma.ts. */
  terminalTextGamma?: number
}

